func (v *AssignStmt) tname() string         { return "AssignStmt" }
func (v *AssignStmt) ttext() (string, bool) { return "", false }
func (v *AssignStmt) tkids() []any          { return nil }
func (v *AssignStmt) tstruct() bool         { return true }
func (v *AssignStmt) tfresh() bool          { return false }
func (v *AssignStmt) tsetFresh(bool)        {}
func (v *AssignStmt) tfield(name string) (any, bool) {
	switch name {
	case "Lhs":
		return func() any {
			if v.Lhs == nil {
				return nil
			}
			kids := make([]any, len(v.Lhs))
			for i, x := range v.Lhs {
				kids[i] = any(x)
			}
			return tlistOf(kids)
		}(), true
	case "Tok":
		return any(v.Tok), true
	case "Rhs":
		return func() any {
			if v.Rhs == nil {
				return nil
			}
			kids := make([]any, len(v.Rhs))
			for i, x := range v.Rhs {
				kids[i] = any(x)
			}
			return tlistOf(kids)
		}(), true
	}
	return nil, false
}

func (v *AssignStmt) tfieldWork(p *tparser, name string) (any, bool) {
	switch name {
	case "Lhs":
		return func() any {
			if v.Lhs == nil {
				return nil
			}
			kids := make([]any, len(v.Lhs))
			for i, x := range v.Lhs {
				p.stepWork()
				kids[i] = any(x)
			}
			return p.listField(kids)
		}(), true
	case "Tok":
		return any(v.Tok), true
	case "Rhs":
		return func() any {
			if v.Rhs == nil {
				return nil
			}
			kids := make([]any, len(v.Rhs))
			for i, x := range v.Rhs {
				p.stepWork()
				kids[i] = any(x)
			}
			return p.listField(kids)
		}(), true
	}
	return nil, false
}

