// tmk_ValueSpec makes a ValueSpec in an action (newStruct in the typed runtime).
func tmk_ValueSpec(c *tctx, final bool, f0 any, f1 any, f2 any) any {
	c.p.stepWork()
	a := c.p.ext.(*tslabs)
	v := astNew(&a.tValueSpec)
	c.p.stepWork()
	v.Names = tl2(a, f0)
	c.p.stepWork()
	v.Type = tAs[Expr](tpub(f1))
	c.p.stepWork()
	v.Values = tl3(a, f2)
	if final {
		v.Span = Span{c.start, c.end}
		return v
	}
	first, start, end := true, 0, 0
	c.p.stepWork()
	spanOf(f0, &first, &start, &end)
	c.p.stepWork()
	spanOf(f1, &first, &start, &end)
	c.p.stepWork()
	spanOf(f2, &first, &start, &end)
	return c.made(v, first, start, end)
}

func tl0(a *tslabs, v any) []*ImportSpec {
	a.stepWork()
	if v == nil {
		return nil
	}
	n, _ := v.(*tnode)
	if n == nil {
		return []*ImportSpec{} // another node (an Error), as conversion makes an empty list of it
	}
	out := astSlice(&a.tl0Chunk, len(n.kids))
	for i, c := range n.kids {
		a.stepWork()
		out[i] = tAs[*ImportSpec](c)
	}
	return out
}

