func (a *astConv) list0(n *Node) []any {
	a.stepWork()
	if n == nil {
		return nil
	}
	out := astSlice(&a.list0Chunk, len(n.Children))
	for i, c := range n.Children {
		a.stepWork()
		out[i] = a.anyValue(c)
	}
	return out
}

